script.inlineScript:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    if (!api.context.props.dispTest)
        return true; // Hide.
    if (api.context.session.user.roles.indexOf('maint') == -1)
        return true; // Hide.
    return false;
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    return api.data.look_up_resolution_framework_enabled.result.value.value !== 'true';
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    if (api.data.look_up_resolution_framework_enabled.result.value.value === 'true' || api.state.health.overall.health === "GREEN")
        return true;
    return false;
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    if (api.data.look_up_resolution_framework_enabled.result.value.value === 'true' || api.state.health.overall.health === "GREEN")
        return true;
    return false;
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
    if (api.state.loading)
        return null; // for indeterminate loading.
    return 0; // force it to zero to hide it.
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    var currentPki = api.state.config.currentPki;
    if (!currentPki)
        return helpers.translateSync("This instance isn't configured to use any PKI.");
    return helpers.translateSync('This instance is currently configured to use {0} as a PKI.', currentPki);
}
